            for (int j = i; j < n; j++) {
                int ni = j + 2;
                if (ni > n) ni = n;
                int nk = k + j - i + 1;
                if (nk <= m) {
                    auto x = multiply(dp2[i][k], dp[j - i + 1]);
                    x.first *= comb(nk, k);
                    x.second *= comb(nk, k);
                    dp2[ni][nk] = add(dp2[ni][nk], x);
                }
            }
            if (i + 1 <= n && k <= m) {
                dp2[i + 1][k] = add(dp2[i + 1][k], dp2[i][k]);
            }
        }
    }
    cout << (int)dp2[n][m].second << "\n";
}

