import java.util.Scanner;

public class Main {
    static final long MOD = 1000000009;
    static final int MAX = 262144;
    static Mint[] fact = new Mint[MAX];
    static Mint[] invFact = new Mint[MAX];
    static Pair[] dp = new Pair[501];
    static Pair[][] dp2 = new Pair[502][501];

    static class Mint {
        long val;

        Mint() {
            this.val = 0;
        }

        Mint(long v) {
            this.val = v % MOD;
            if (this.val < 0) this.val += MOD;
        }

        public int toInt() {
            return (int) val;
        }

        public Mint add(Mint other) {
            long res = this.val + other.val;
            if (res >= MOD) res -= MOD;
            return new Mint(res);
        }

        public Mint subtract(Mint other) {
            long res = this.val - other.val;
            if (res < 0) res += MOD;
            return new Mint(res);
        }

        public Mint multiply(Mint other) {
            long res = (this.val * other.val) % MOD;
            return new Mint(res);
        }

        public Mint pow(long n) {
            Mint res = new Mint(1);
            Mint base = this;
            while (n > 0) {
                if ((n & 1) == 1) res = res.multiply(base);
                base = base.multiply(base);
                n >>= 1;
            }
            return res;
        }

        public static Mint one() {
            return new Mint(1);
        }

        public static Mint zero() {
            return new Mint(0);
        }
    }

    static class Pair {
        Mint first;
        Mint second;

        Pair(Mint first, Mint second) {
            this.first = first;
            this.second = second;
        }
    }

    static long inv(long a, long p) {
        if (a == 1) return 1;
        return (1 - p * inv(p % a, a)) / a + p;
    }

    static void initFactorials() {
        fact[0] = new Mint(1);
        for (int i = 1; i < MAX; i++) {
            fact[i] = fact[i - 1].multiply(new Mint(i));
        }
        invFact[MAX - 1] = new Mint(1).divide(fact[MAX - 1]);
        for (int i = MAX - 2; i >= 0; i--) {
            invFact[i] = invFact[i + 1].multiply(new Mint(i + 1));
        }
    }

    static Mint comb(int a, int b) {
        if (a < 0 || b < 0 || a < b) return new Mint(0);
        return fact[a].multiply(invFact[b]).multiply(invFact[a - b]);
    }

    static Pair multiply(Pair a, Pair b) {
        return new Pair(a.first.multiply(b.first), a.second.multiply(b.first).add(a.first.multiply(b.second)));
    }

    static Pair add(Pair a, Pair b) {
        return new Pair(a.first.add(b.first), a.second.add(b.second));
    }

    static void setup() {
        initFactorials();
        dp[0] = new Pair(new Mint(1), new Mint(0));
        dp[1] = new Pair(new Mint(2), new Mint(0));
        for (int n = 2; n <= 500; n++) {
            Pair sumPair = new Pair(new Mint(0), new Mint(0));
            for (int j = 0; j < n; j++) {
                Mint cnt = new Mint(n + 1);
                Mint sum = new Mint(0);
                for (int k = 0; k < n; k++) {
                    sum = sum.add(new Mint(Math.abs(j - k)));
                }
                Pair left = dp[j];
                Pair right = dp[n - 1 - j];
                Pair x = multiply(left, right);
                x.first = x.first.multiply(comb(n - 1, j));
                x.second = x.second.multiply(comb(n - 1, j));
                x.first = x.first.multiply(cnt);
                x.second = x.second.multiply(cnt).add(sum.multiply(cnt));
                sumPair = add(sumPair, x);
            }
            dp[n] = sumPair;
        }
    }

    public static void process(Scanner sc) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        setup();
        for (int i = 0; i <= n; i++) {
            for (int k = 0; k <= m; k++) {
                dp2[i][k] = new Pair(Mint.zero(), Mint.zero());
            }
        }
        dp2[0][0] = new Pair(new Mint(1), new Mint(0));
        for (int i = 0; i < n; i++) {
            for (int k = 0; k <= m; k++) {
                if (dp2[i][k].first.val == 0 && dp2[i][k].second.val == 0) continue;
                for (int j = i; j < n; j++) {
                    int ni = j + 2;
                    if (ni > n) ni = n;
                    int nk = k + j - i + 1;
                    if (nk <= m) {
                        Pair x = multiply(dp2[i][k], dp[j - i + 1]);
                        x.first = x.first.multiply(comb(nk, k));
                        x.second = x.second.multiply(comb(nk, k));
                        dp2[ni][nk] = add(dp2[ni][nk], x);
                    }
                }
                if (i + 1 <= n && k <= m) {
                    dp2[i + 1][k] = add(dp2[i + 1][k], dp2[i][k]);
                }
            }
        }
        System.out.println(dp2[n][m].second.toInt());
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        process(sc);
        sc.close();
    }
}
